"""Thin ctypes bindings for the Rust real-time runtime shipped with the image."""
import ctypes
import os
from pathlib import Path


def _load_runtime():
    candidates = [
        os.environ.get("SELKIES_NATIVE_LIBRARY", ""),
        "/usr/local/lib/libselkies_upload_sidecar.so",
        str(Path(__file__).resolve().parents[4] / "libselkies_upload_sidecar.so"),
    ]
    errors = []
    for candidate in candidates:
        if not candidate:
            continue
        try:
            return ctypes.CDLL(candidate)
        except OSError as error:
            errors.append(f"{candidate}: {error}")
    raise RuntimeError("Selkies Rust runtime library is unavailable: " + "; ".join(errors))


_LIBRARY = _load_runtime()

_LIBRARY.selkies_audio_queue_new.argtypes = [ctypes.c_size_t]
_LIBRARY.selkies_audio_queue_new.restype = ctypes.c_void_p
_LIBRARY.selkies_audio_queue_push.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t]
_LIBRARY.selkies_audio_queue_push.restype = ctypes.c_int
_LIBRARY.selkies_audio_queue_pop.argtypes = [
    ctypes.c_void_p, ctypes.c_void_p, ctypes.c_size_t, ctypes.POINTER(ctypes.c_size_t)
]
_LIBRARY.selkies_audio_queue_pop.restype = ctypes.c_int
_LIBRARY.selkies_audio_queue_len.argtypes = [ctypes.c_void_p]
_LIBRARY.selkies_audio_queue_len.restype = ctypes.c_size_t
_LIBRARY.selkies_audio_queue_dropped.argtypes = [ctypes.c_void_p]
_LIBRARY.selkies_audio_queue_dropped.restype = ctypes.c_uint64
_LIBRARY.selkies_audio_queue_free.argtypes = [ctypes.c_void_p]
_LIBRARY.selkies_audio_queue_free.restype = None

_LIBRARY.selkies_xtest_open.argtypes = [ctypes.c_char_p]
_LIBRARY.selkies_xtest_open.restype = ctypes.c_void_p
_LIBRARY.selkies_xtest_key.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_int]
_LIBRARY.selkies_xtest_key.restype = ctypes.c_int
_LIBRARY.selkies_xtest_close.argtypes = [ctypes.c_void_p]
_LIBRARY.selkies_xtest_close.restype = None


class RustAudioQueue:
    def __init__(self, capacity=10, max_chunk_bytes=65536):
        self._handle = _LIBRARY.selkies_audio_queue_new(int(capacity))
        if not self._handle:
            raise RuntimeError("Could not create Rust audio queue")
        self._max_chunk_bytes = int(max_chunk_bytes)

    def push_pointer(self, pointer, length):
        if not self._handle or not pointer or length <= 0:
            return -1
        address = ctypes.cast(pointer, ctypes.c_void_p)
        return int(_LIBRARY.selkies_audio_queue_push(self._handle, address, int(length)))

    def pop(self):
        if not self._handle:
            return None
        output = ctypes.create_string_buffer(self._max_chunk_bytes)
        output_length = ctypes.c_size_t()
        result = int(_LIBRARY.selkies_audio_queue_pop(
            self._handle, output, self._max_chunk_bytes, ctypes.byref(output_length)
        ))
        if result == 0:
            return None
        if result < 0:
            raise RuntimeError(f"Rust audio queue pop failed: {result}")
        return output.raw[:output_length.value]

    @property
    def size(self):
        return int(_LIBRARY.selkies_audio_queue_len(self._handle)) if self._handle else 0

    @property
    def dropped(self):
        return int(_LIBRARY.selkies_audio_queue_dropped(self._handle)) if self._handle else 0

    def close(self):
        if self._handle:
            _LIBRARY.selkies_audio_queue_free(self._handle)
            self._handle = None


class RustXTestKeyboard:
    def __init__(self, display_name=None):
        encoded = (display_name or os.environ.get("DISPLAY", "")).encode("utf-8") or None
        self._handle = _LIBRARY.selkies_xtest_open(encoded)
        if not self._handle:
            raise RuntimeError("Could not initialize Rust XTEST keyboard")

    def key(self, keycode, pressed):
        if not self._handle:
            raise RuntimeError("Rust XTEST keyboard is closed")
        result = int(_LIBRARY.selkies_xtest_key(self._handle, int(keycode), 1 if pressed else 0))
        if result != 0:
            raise RuntimeError(f"Rust XTEST injection failed: {result}")

    def close(self):
        if self._handle:
            _LIBRARY.selkies_xtest_close(self._handle)
            self._handle = None
